def amicable_numbers_sum(limit):
    def sum_divisors(n):
        divisors = [1]
        for i in range(2, int(n**0.5)+1):
            if n % i == 0:
                divisors.append(i)
                if i != n // i:
                    divisors.append(n // i)
        return sum(divisors)

    amicable_sum = 0
    for i in range(1, limit+1):
        sum_i = sum_divisors(i)
        if sum_i > i and sum_divisors(sum_i) == i:
            amicable_sum += i + sum_i

    return amicable_sum

