    def binomial_coefficient(n, k):
        if k == 0 or k == n:
            return 1
        if k > n - k:
            k = n - k
        res = 1
        for i in range(k):
            res = res * (n - i)
            res = res // (i + 1)
        return res

    sum_even = 0
    for i in range(n+1):
        if i % 2 == 0:
            sum_even += binomial_coefficient(n, i)

    return sum_even

